/**  The single most appropriate next step for one edge. */
export type RelationGovernanceAction =
/**  用户术语：「纳入集中库管理」。 */
"centralize_management" |
/**  移除 SkillHub 创建的目标入口；沿用既有移除影响预览。 */
"undeploy" |
/**  重新检查/重新扫描后回到清单；不写文件、不写关系事实。 */
"revalidate" |
/**  来源副本转用户自留（复用既有 KeepIndependentCopy 命令）。 */
"keep_independent_copy" |
/**  部署副本解除受管但保留目标文件（复用既有 DetachManagement 命令）。 */
"detach_keep_files" |
/**  受阻或无适用动作。 */
"none";

/**
 *  Which governance change a batch applies to every selected relationship
 *  edge.
 */
export type RelationGovernanceBatchAction =
/**
 *  用户术语「纳入集中库管理」：复用 required-backup ManagedLink 的
 *  prepare/commit/rollback 四段安全链路。
 */
"centralize_management" |
/**
 *  保留来源副本（计划 8.9/8.16）：逐行复用单条 RetainSourceCopy 的
 *  账本写入与治理历史，绝不触碰来源目录。
 */
"retain_source_copy" |
/**
 *  清理来源副本（计划 8.9/8.16）：逐行复用单条 cleanup 状态机
 *  （prepare → 备份 → checkpoint → 删除 → 原子归档），并要求逐行
 *  携带显式确认。
 */
"clean_source_copy";

/**
 *  One child item of a governance batch.  `operation_id` is the child
 *  operation, so the parent operation log can be followed to each item.
 */
export type RelationGovernanceBatchItem = {
	relation_id: string,
	operation_id: OperationId | null,
	state: RelationGovernanceBatchItemState,
	error_code: ErrorCode | null,
	detail: string | null,
	/**  用户可对该行单独重试。 */
	retryable: boolean,
	rollback_available: boolean,
	backup_path: string | null,
	affected_paths: string[],
	blockers: RelationGovernanceBlocker[],
};

export type RelationGovernanceBatchItemState = "prepared" | "committed" | "rolled_back" | "failed" |
/**  准备阶段就按事实判定为不可执行，未触碰文件系统。 */
"blocked" |
/**  用户在预览后取消该行；其余行不受影响。 */
"cancelled";

export type RelationGovernanceBatchOutcome = {
	batch_id: OperationId,
	action: RelationGovernanceBatchAction,
	state: RelationGovernanceBatchState,
	items: RelationGovernanceBatchItem[],
	prepared_count: number,
	committed_count: number,
	failed_count: number,
	blocked_count: number,
	cancelled_count: number,
	relationship_revision: string,
};

export type RelationGovernanceBatchState = "prepared" | "committed" |
/**  部分成功：成功项保留，失败项逐项可重试或回退。 */
"partially_committed" | "failed" | "cancelled";

/**
 *  Why an edge is not `EligibleToCentralize`.  The list is exhaustive and
 *  ordered, so a caller can show the first reason and the full set.
 */
export type RelationGovernanceBlocker =
/**  目录联接或未知表示：目标无法被安全校验，禁止转换。 */
"unverifiable_representation" |
/**  关系类型没有可转换的入口（未知关系、导入副本等）。 */
"relationship_not_convertible" |
/**  该条目本身就是共享目录的读取入口；转换会改写共享本体。 */
"shared_body_protected" |
/**  条目不在任何已登记目录节点下。 */
"directory_not_registered" |
/**  Agent 对该目录的识别状态未知，必须先复核。 */
"directory_recognition_unknown" |
/**  Agent 对该目录的识别状态为不支持，禁止操作。 */
"directory_recognition_unsupported" |
/**  存证不是"指纹一致"状态，必须先重新校验。 */
"verification_not_current" |
/**  其他 Agent 读取同一共享目录，共享影响必须由用户显式确认。 */
"shared_impact_confirmation_required" |
/**  关系缺少确定性的 Skill 身份或内容指纹。 */
"skill_identity_unconfirmed";

/**
 *  The four quick filters of the governance list.  They select from one
 *  ledger; they are not four separate pages.
 */
export type RelationGovernanceBucket = "all" | "eligible_to_centralize" | "needs_validation" | "blocked";

export type RelationGovernanceCounts = {
	all: number,
	eligible_to_centralize: number,
	needs_validation: number,
	blocked: number,
	/**  五个快捷状态计数（plan 7.9）。 */
	status_normal: number,
	status_retained: number,
	status_needs_validation: number,
	status_needs_attention: number,
	status_blocked: number,
	/**  两侧 kind 计数。 */
	source_copies: number,
	deployments: number,
};

export type RelationGovernanceFilters = {
	bucket?: RelationGovernanceBucket,
	skill_id?: SkillId | null,
	agent_client_id?: string | null,
	text?: string,
	relationship_types?: RelationshipType[],
	/**  项目 scope：命中来源副本的 source_container_id。 */
	project_id?: string | null,
	/**  来源类别过滤；部署边不受此过滤影响。 */
	source_class?: ImportSourceClass | null,
	/**  批次过滤：只命中 import_batch_items 映射的关系（由服务层传入集合）。 */
	batch_id?: string | null,
	/**  五个快捷状态过滤；空集合表示不过滤。 */
	statuses?: GovernableRelationStatus[],
};

/**  行上的影响范围：另一端的消费者、同一 Skill 的其它路径与备份回退条件。 */
export type RelationGovernanceImpact = {
	other_consumer_agent_ids: string[],
	other_skill_paths: RelatedSkillPath[],
	backup_required: boolean,
	rollback_available: boolean,
};

export type RelationGovernanceLedger = {
	rows: RelationGovernanceRow[],
	counts: RelationGovernanceCounts,
	bucket: RelationGovernanceBucket,
	total: number,
	relationship_revision: string,
	last_verified_at: string | null,
};

/**  Whether an edge can be brought under central-library management. */
export type RelationGovernanceReadiness =
/**
 *  Convertible now: content verified, directory recognized, no shared body
 *  rewrite and no other consumer of the same shared directory.
 */
"eligible_to_centralize" |
/**
 *  Convertible in principle, but the evidence is stale or an explicit
 *  confirmation is still outstanding.
 */
"needs_validation" |
/**  Not convertible until the listed fact-level obstacle is resolved. */
"blocked" |
/**  Already a managed/observed link, so there is nothing to centralize. */
"already_centralized";

/**
 *  One relationship edge, ready for display and for batch selection. The
 *  tagged `relation` carries either a source-copy edge or a deployment edge;
 *  the accessors below keep call sites free of enum plumbing.
 */
export type RelationGovernanceRow = {
	/**  对象、关系类型、目标路径、存证与验证状态的唯一事实来源。 */
	relation: GovernableRelationFact,
	/**
	 *  五个快捷状态（plan 7.1/7.9）：Normal/Retained/NeedsValidation/
	 *  NeedsAttention/Blocked。
	 */
	status: GovernableRelationStatus,
	skill_display_name: string | null,
	readiness: RelationGovernanceReadiness,
	primary_action: RelationGovernanceAction,
	blockers: RelationGovernanceBlocker[],
	impact: RelationGovernanceImpact,
};

