/**  状态与已持久化事实一致，未推进 revision。 */
"unchanged" |
/**  因 MissingWithAccessibleParent 归档并写入 ExternalRemoved 历史。 */
"archived" |
/**  本项检查失败（探测错误或写入错误），保留活动关系。 */
"failed";

